package com.lqq.supportflow.knowledge.application;
import com.lqq.supportflow.knowledge.domain.*; import org.springframework.stereotype.Service;
@Service public class GetDocumentIngestionProgressService { private final KnowledgeDocumentPort documents; private final KnowledgeChunkPort chunks; public GetDocumentIngestionProgressService(KnowledgeDocumentPort documents,KnowledgeChunkPort chunks){this.documents=documents;this.chunks=chunks;} public DocumentIngestionProgress get(Long tenantId,Long knowledgeBaseId,Long documentId){KnowledgeDocument document=documents.findById(tenantId,knowledgeBaseId,documentId).orElseThrow(()->new IllegalArgumentException("document does not belong to tenant"));return new DocumentIngestionProgress(document.id(),document.status(),chunks.count(tenantId,knowledgeBaseId,documentId));}}
